import"./chunk-2NFLSA4Y.js";var n={foucault:{theory:{concept:"[[A Foucault pendulum is a long, heavy pendulum free to swing in any direction, whose plane of swing slowly turns relative to the floor because the Earth rotates.]] Nothing pushes the pendulum sideways, but the floor under it turns with the Earth, so, seen from the room, the swing slowly turns."},section:{sand:{title:"The sand pendulum",text:"Hang a funnel full of sand on a long string and let it swing. The thin stream of sand draws the funnel's path on the table, so you can see the whole motion at once. Unlike an ordinary pendulum, this one can swing in any direction: it is a spherical pendulum."},shapes:{title:"Line, ellipse or circle",text:"Pulled aside and released, the pendulum swings in a straight line through the centre. A push sideways at the moment of release makes it go round: a small push gives a narrow ellipse, a bigger one a wider ellipse, and exactly the right push a circle (a conical pendulum). Pushing the other way makes it go round in the opposite direction."},foucault:{title:"Foucault's pendulum: the Earth turns",text:"Nothing pushes a well-released pendulum sideways, so it keeps swinging in the same direction in space. [[But the Earth rotates once a day, carrying the floor and the sand table with it.]] Seen from the room, the swing slowly turns: in the northern hemisphere clockwise when seen from above. The star pattern in the sand is the proof that the Earth rotates."},latitude:{title:"It depends on where you are",text:"At the North Pole the floor turns completely under the pendulum once a day (23.93 h), so the swing turns 15\xB0 every hour. [[At the equator the floor does not turn around the vertical at all, so the swing does not turn.]] In between, the rate is 15\xB0 \xB7 sin \u03C6 per hour: about 10\xB0 per hour in Tbilisi, a full turn in about 36 h. In the southern hemisphere it turns the other way."},history:{title:"Paris, 1851",text:"L\xE9on Foucault hung a 28 kg ball on a 67 m wire under the dome of the Panth\xE9on in Paris. Each swing took about 16 s, and a pin under the ball cut marks in a ridge of sand. Within an hour, visitors could see the swing turn by about 11\xB0 \u2014 the first direct demonstration in a room that the Earth rotates."},rosette:{title:"Why the release must be perfect",text:"Even without the Earth's rotation, an elliptical swing turns slowly by itself: the long axis of the ellipse advances in the direction of motion, drawing a rosette. The rate is about (3/8)\xB7\u03C9\u2080\xB7a\xB7b / L\xB2, where a and b are the half-axes of the ellipse. A tiny sideways push can hide or fake the Earth's effect, so Foucault pendulums are released very carefully \u2014 traditionally by burning the thread that holds the ball."},check:{title:"Check your understanding",text:"Which push gives a straight line? (None.) Which way does a Foucault pendulum turn in Sydney? (Counter-clockwise.) How long does a full turn take at the North Pole? (About 24 h.) Why does it not turn at the equator? Try each answer in the simulation."}},formula:{period:"Time of one swing (the same as an ordinary pendulum)",rate:"How fast the swing turns at latitude \u03C6",turnTime:"Time for a full turn of the swing",coriolis:"Coriolis acceleration in the rotating frame of the Earth",rosette:"Turning of an elliptical swing by itself (a, b: half-axes of the ellipse)"},variable:{latitude:"Latitude (north positive, south negative)",length:"Length of the string",period:"Time of one full swing",earth:"Angular velocity of the Earth (one turn per 23.93 h)"},assumption:{point:"The bob is a point mass on a light string that stays taut; the pivot has no friction.",speedUp:"To see the effect in seconds, the Earth's rotation is sped up by the factor you choose. The real turning time is shown separately.",centrifugal:"The Earth's centrifugal effect only changes g very slightly and is included in g.",loss:"Energy loss (air, sand) is a simple drag that shrinks the swing by the chosen percentage every full swing.",scale:"The scene is scaled so that the pattern fills the table, and the funnel is drawn larger than scale.",circle:"A circular swing has no farthest point, so its turning is not measured."},param:{mode:"Experiment",length:"String length",amplitude:"Release angle",push:"Sideways push",latitude:"Latitude",speedUp:"Earth's rotation sped up \xD7",energyLoss:"Swing lost per full swing",timeStep:"Simulation timestep"},hint:{length:"Foucault's pendulum in Paris was 67 m long.",push:"0 % \u2014 a straight line. 100 % \u2014 exactly the push for a circle. Negative \u2014 round the other way.",latitude:"North of the equator positive, south negative. Tbilisi is at 41.7\xB0.",speedUp:"The real Earth would need hours. Here it turns this many times faster.",energyLoss:"Air and sand slowly take energy away, so the swing shrinks."},preset:{sand:"Sand pendulum",foucault:"Foucault's pendulum (rotating Earth)",line:"Line",ellipse:"Ellipse",circle:"Circle",tbilisi:"Tbilisi",paris:"Paris",northPole:"North Pole",equator:"Equator",sydney:"Sydney"},measure:{turn:"Turn of the swing (+ counter-clockwise)",realTurnHours:"Full turn on the real Earth",radius:"Distance from the centre",swingPeriod:"Time of one swing",expectedTurn:"Turn predicted by the formula",roundness:"Roundness (short \xF7 long axis)",height:"Rise of the bob"},view:{north:"N",east:"E",south:"S",west:"W",planeTurned:"The swing has turned {turn} {direction}",clockwise:"clockwise",counterClockwise:"counter-clockwise",circle:"Circular swing",patternTurned:"The pattern has turned {turn}",speedUp:"Earth sped up {factor}\xD7 \xB7 real full turn: {hours}",equator:"At the equator the swing does not turn",traceOption:"Sand trace",directionOption:"Swing direction"},graph:{turn:"Turn of the swing against time",path:"Path seen from above (north against east)",north:"North"},challenge:{line:{title:"A straight line",description:"Make the sand pendulum draw one straight line for at least 30 s.",hint:"Release it without any sideways push."},circle:{title:"A perfect circle",description:"Make the sand pendulum go round in a circle.",hint:"The push must be exactly right: 100 % (or \u2212100 %)."},tbilisi:{title:"Foucault in Tbilisi",description:"Put the Foucault pendulum in Tbilisi and watch its swing turn by 90\xB0.",hint:"Choose Tbilisi (41.7\xB0). How long would a quarter turn take on the real Earth?"},equator:{title:"On the equator",description:"Put the pendulum on the equator and let it swing for a minute. Does the swing turn?",hint:"At the equator the floor does not turn around the vertical."},south:{title:"Down under",description:"Make the swing turn at least 45\xB0 counter-clockwise.",hint:"Try a place in the southern hemisphere, such as Sydney."},rosette:{title:"A rosette without the Earth",description:"Without the Earth's rotation, make the sand pattern turn by at least 45\xB0.",hint:"An ellipse turns faster when it is wide and the swing is large compared with the string: big release angle, short string, push of about 50 %."}}}},i={sim:n};export{i as default,n as sim};
